class HTML { val children = mutableListOf<Element>() }
class Body { val children = mutableListOf<Element>() }
open class Element(val text: String)
class H1(text: String) : Element(text)
class P(text: String) : Element(text)

fun html(block: HTML.() -> Unit) = HTML().apply(block)
fun HTML.body(block: Body.() -> Unit) {
    children += Body().apply(block)
}
fun Body.h1(text: String) { children += H1(text) }
fun Body.p(text: String) { children += P(text) }

// Usage — reads like HTML
val page = html {
    body {
        h1("Welcome")
        p("This is type-safe!")
    }
}

@DslMarker
annotation class HtmlDsl

@HtmlDsl
class Table { fun tr(block: Row.() -> Unit) { /*...*/ } }

@HtmlDsl
class Row { fun td(text: String) { /*...*/ } }

fun table(block: Table.() -> Unit) = Table().apply(block)

table {
    tr {
        td("Cell 1")
        // tr { }  // ❌ Compile error! Can't access Table here
        // Without @DslMarker this would compile and be a bug
        this@table.tr { td("Explicit access") }  // ✅ OK
    }
}

// Lambda with receiver type
fun buildGreeting(block: StringBuilder.() -> Unit): String {
    val sb = StringBuilder()
    sb.block()  // 'this' inside block is the StringBuilder
    return sb.toString()
}

val result = buildGreeting {
    append("Hello, ")  // 'this' is StringBuilder
    append("World!")
    appendLine()
    append("Welcome to Kotlin DSLs")
}
// "Hello, World!\nWelcome to Kotlin DSLs"
